{
  "version": 1,
  "kind": "ArchitectureContract",
  "styles": [
    "layered"
  ],
  "domains": {
    "billing": {
      "owner": "team-billing",
      "paths": [
        "src/billing/**"
      ],
      "public_interfaces": [
        "src/billing/api.py"
      ]
    }
  },
  "rules": [
    {
      "id": "no-apps",
      "kind": "forbidden-dependency",
      "source": [
        "core/**"
      ],
      "target": [
        "apps/**"
      ],
      "severity": "block",
      "reason": "Core cannot import applications.",
      "remediation": "Use the existing core port."
    },
    {
      "id": "cycles",
      "kind": "cycles",
      "reason": "No cycles here.",
      "remediation": "Invert."
    }
  ],
  "exceptions": [
    {
      "id": "ex-1",
      "rule_id": "no-apps",
      "paths": [
        "core/legacy.py"
      ],
      "reason": "Legacy exemption pending.",
      "expires": "2030-01-31"
    }
  ],
  "extensions": {
    "entities": [
      "x-acme:Widget"
    ],
    "relationships": [
      "x-acme:FEEDS"
    ]
  }
}
